def findTotal(text: String): Either[String, String] = {
  val lines = text.split("
")
  for (i <- lines.indices) {
    if (lines(i).contains("object Orders") && lines(i + 1).contains("def total")) {
      return Right(lines(i + 1))
    }
  }
  Left("Could not find 'def total' inside 'object Orders'")
}

