object Equivalence {
  def imports(text: String): Vector[String] = {
    text.split("
").filter(line => line.startsWith("package") || line.startsWith("import")).map { line =>
      if (line.startsWith("package")) {
        val parts = line.split(" ")
        if (parts.length >= 2) parts(1)
      } else {
        val parts = line.split(" ")
        if (parts.length >= 2) parts(1)
      }
    }.toVector
  }
}

