def needsSeed(relation: String): Boolean = {
  relation match {
    case "symdex.prelude.Relation1" => true
    case "symdex.prelude.Relation2" => true
    case _ => false
  }
}

def needsSeed(relation: String): Boolean = {
  relation match {
    case "symdex.+" | "symdex.==" | "symdex.!=" | "symdex.<" | "symdex.>" | "symdex.<= " | "symdex.>= " => true
    case _ => false
  }
}

def listTmp(): Either[String, Ran] = {
  val process = Exec.runProcess("ls", Seq("/tmp"), timeout = 5 seconds)
  process.map {
    case (exitCode, output) =>
      if (exitCode == 0) Right(Ran(output))
      else Left(s"Command failed with exit code $exitCode")
  }.getOrElse(Left("Process execution failed"))
}

