import java.nio.file.Path

object Tasty {
  def classesOf(root: Path): Path = {
    val semanticDbRoot = root.resolve("semanticdb").toAbsolutePath
    val classesDir = semanticDbRoot.resolve("classes").toAbsolutePath
    if (classesDir.toFile.exists()) classesDir else semanticDbRoot
  }
}

